(function(){
'use strict';
const STORE='sierra_times_issues_v1',CLIENT=crypto.randomUUID(),COLORS={orange:'#ff7824',teal:'#16cdbe',blue:'#009fff',green:'#3ed600',violet:'#9e00cb',yellow:'#ffc529',red:'#e80000'};
const blockLabels={story:'Nota',photo:'Fotografía',quote:'Destacado',insert:'Inserto',cta:'Llamado a la acción',contact:'Contacto',link:'Enlace',orgchart:'Organigrama',note:'Nota editorial'};
const POLICY_TOPICS=['Seguridad y salud','Ética y cumplimiento','Sostenibilidad','Calidad','Cultura y convivencia'];
let issues=[],active=null,pageId=null,blockId=null,tab='design',saveTimer=null,channel=null,remoteChannel=null,peers=new Map(),exporting=false;
const assetPreviews=new Map(),legacyAssets=new Map();
const uid=()=>crypto.randomUUID(),icon=(name,size=16)=>typeof siIcon==='function'?siIcon(name,size):'';
const safe=value=>typeof esc==='function'?esc(value):String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=value=>typeof escAttr==='function'?escAttr(value):safe(value);
const monthName=date=>new Intl.DateTimeFormat('es-GT',{month:'long',year:'numeric'}).format(new Date(`${date}T12:00:00`)).replace(/^./,c=>c.toUpperCase());
const todayMonth=()=>{const date=new Date();if(date.getDate()>=20)date.setMonth(date.getMonth()+1,1);return`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-01`};
const defaultBlocks=page=>page===1?[]:[
  {id:uid(),type:'story',span:12,accent:'teal',kicker:'Desde nuestras sedes',title:'Una historia por contar',deck:'',body:'Agrega la información de la nota. Dentro de ella puedes combinar fotografías, enlaces, llamados a la acción y contactos.',author:'',country:'',site:'',items:[]}
];
function newPage(number,kind='editorial'){const page={id:uid(),title:number===1?'Portada':`Página ${number}`,layout:number===1?'cover':'editorial',kind,mandatory:kind!=='editorial',accent:Object.keys(COLORS)[(number-1)%Object.keys(COLORS).length],footerText:'',blocks:kind==='editorial'||kind==='cover'?defaultBlocks(number):[]};if(kind==='credits-policy')Object.assign(page,{title:'Créditos',credits:{direction:'Edición y coordinación SIERRA Times',talent:'Equipos de Talento Humano de todas las empresas SIERRA',design:'Marketing SIERRA',texts:'Colaboradores SIERRA',photography:'Fotografías aportadas por nuestros equipos',contact:''}});if(kind==='activities')Object.assign(page,{title:'Actividades del mes',activities:[]});if(kind==='new-hires')Object.assign(page,{title:'Nuevos ingresos',people:[]});if(kind==='birthdays-current')Object.assign(page,{title:'Cumpleaños del mes',people:[]});if(kind==='birthdays-next')Object.assign(page,{title:'Próximos cumpleaños',people:[]});return page}

function newIssue(){const month=todayMonth(),kinds=['cover','credits-policy','editorial','editorial','activities','new-hires','birthdays-current','birthdays-next'];return{id:uid(),title:`SIERRA Times · ${monthName(month)}`,month,state:'working',version:1,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),finalizedAt:null,pages:kinds.map((kind,index)=>newPage(index+1,kind)),comments:[],assets:[],settings:{showMasthead:true,printIntensity:'balanced'}}}

function normalizeIssue(issue){if(issue?.state==='final')return issue;const pages=issue?.pages;if(!Array.isArray(pages)||!pages.length)return issue;const cover=pages.find(page=>page.layout==='cover')||pages[0];cover.kind='cover';cover.mandatory=true;cover.footerText=cover.footerText||'';const stories=cover.blocks?.filter(block=>block.type==='story')||[];const loose=cover.blocks?.filter(block=>block.type!=='story')||[];stories.forEach((story,index)=>{story.pageRef=story.pageRef||`PÁGINA ${index+3}`;story.items=Array.isArray(story.items)?story.items:[];story.items.filter(item=>item.type==='photo').forEach(item=>item.height=item.height||'medium')});if(stories[0]&&loose.length){stories[0].items.push(...loose.map(block=>({...block,id:block.id||uid()})));cover.blocks=stories}if(stories.length===1)cover.blocks.push({id:uid(),type:'story',span:4,accent:'blue',kicker:'En esta edición',title:'Una historia que continúa en el interior',deck:'Presenta aquí otra nota relevante de la edición.',pageRef:'PÁGINA 4',items:[]});pages.forEach(page=>{page.footerText=page.footerText||'';(page.blocks||[]).filter(block=>block.type==='story').forEach(block=>{block.items=Array.isArray(block.items)?block.items:[];block.items.filter(item=>item.type==='photo').forEach(item=>item.height=item.height||'medium')})});if(!pages.some(page=>page.kind==='credits-policy'))pages.splice(1,0,newPage(2,'credits-policy'));const creditsPage=pages.find(page=>page.kind==='credits-policy');if(creditsPage){creditsPage.mandatory=true;creditsPage.title='Créditos';creditsPage.credits=creditsPage.credits||{};creditsPage.credits.direction=creditsPage.credits.direction||creditsPage.editorName||'Edición y coordinación SIERRA Times';creditsPage.credits.photography=creditsPage.credits.photography||'Fotografías aportadas por nuestros equipos';creditsPage.credits.contact=creditsPage.credits.contact||''}const required=[['activities','Actividades del mes'],['new-hires','Nuevos ingresos'],['birthdays-current','Cumpleaños del mes'],['birthdays-next','Próximos cumpleaños']];required.forEach(([kind])=>{const found=pages.find(page=>page.kind===kind);if(found){found.mandatory=true;if(kind==='activities')found.activities=Array.isArray(found.activities)?found.activities:[];else found.people=Array.isArray(found.people)?found.people:[]}else pages.push(newPage(pages.length+1,kind))});const closing=required.map(([kind])=>pages.find(page=>page.kind===kind));issue.pages=pages.filter(page=>!required.some(([kind])=>kind===page.kind)).concat(closing);issue.pages.forEach((page,index)=>{page.title=page.title||`Página ${index+1}`});while(issue.pages.length%4)issue.pages.splice(issue.pages.length-4,0,newPage(issue.pages.length-3,'editorial'));return issue}

function load(){try{issues=JSON.parse(localStorage.getItem(STORE)||'[]')}catch{issues=[]}if(!Array.isArray(issues))issues=[];issues=issues.map(normalizeIssue)}

function lightweightIssues(){return JSON.parse(JSON.stringify(issues,(key,value)=>typeof value==='string'&&/^data:image\//i.test(value)?'':value))}

function writeLocal(){try{localStorage.setItem(STORE,JSON.stringify(lightweightIssues()));return true}catch(error){console.warn('Guardado local de SIERRA Times:',error);notify('No se pudo guardar la copia local. La edición continúa respaldándose en línea.');return false}}

function durableAsset(value){const source=String(value||'');return typeof policyDurableAssetUrl==='function'?policyDurableAssetUrl(source):source}
async function hydrateAssets(root=document){if(typeof indexAssets==='undefined')return;try{await indexAssets.images(root)}catch(error){console.warn('No se pudieron preparar algunas imágenes de SIERRA Times:',error)}}
async function storeAssetSource(source,issueId=active?.id){const value=String(source||'');if(!value||!/^data:image\//i.test(value))return durableAsset(value);if(legacyAssets.has(value))return legacyAssets.get(value);const task=(async()=>{if(typeof sb==='undefined'||typeof me==='undefined'||!me?.id)throw Error('Inicia sesión para guardar imágenes en SIERRA Times.');const blob=await(await fetch(value)).blob(),extension=blob.type==='image/png'?'png':blob.type==='image/jpeg'?'jpg':'webp',path=`newsletter/${issueId||'issue'}/${me.id}/${uid()}.${extension}`;const{error}=await sb.storage.from('product-images').upload(path,blob,{contentType:blob.type||'image/webp',upsert:false,cacheControl:'3600'});if(error)throw Error('No se pudo guardar la imagen en línea. '+error.message);const reference=durableAsset(sb.storage.from('product-images').getPublicUrl(path).data.publicUrl);assetPreviews.set(reference,value);return reference})();legacyAssets.set(value,task);try{return await task}catch(error){legacyAssets.delete(value);throw error}}
async function storeAssetFile(file,issueId=active?.id){if(!file?.type?.startsWith('image/'))throw Error('Selecciona una imagen.');if(file.size>15*1024*1024)throw Error('La imagen supera 15 MB. Elige una versión más ligera.');const allowed=new Set(['image/png','image/jpeg','image/webp','image/avif']);if(!allowed.has(file.type))throw Error('Usa una imagen PNG, JPG, WebP o AVIF.');let source;if(typeof commsPrepareImageFile==='function')source=await commsPrepareImageFile(file,{maxDimension:3200,quality:.92});else source=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});return storeAssetSource(source,issueId)}
async function migrateIssueAssets(issue){if(!issue)return false;let changed=false;const visit=async value=>{if(typeof value==='string'){if(/^data:image\//i.test(value)){const stored=await storeAssetSource(value,issue.id);changed=changed||stored!==value;return stored}return durableAsset(value)}if(Array.isArray(value))return Promise.all(value.map(visit));if(value&&typeof value==='object'){for(const key of Object.keys(value))value[key]=await visit(value[key])}return value};try{await visit(issue);return changed}catch(error){console.warn('Migración de recursos de SIERRA Times:',error);notify('Una imagen anterior no pudo migrarse todavía. No se eliminó; vuelve a intentarlo con conexión.');return false}}
async function loadCloud(){if(typeof sb==='undefined'||typeof me==='undefined'||!me?.id)return;try{const{data,error}=await sb.from('newsletter_issues').select('payload').order('issue_month',{ascending:false});if(error||!Array.isArray(data))return;const local=new Map(issues.map(issue=>[issue.id,issue]));data.forEach(row=>{const issue=normalizeIssue(row.payload);if(issue?.id&&(!local.has(issue.id)||issue.updatedAt>local.get(issue.id).updatedAt))local.set(issue.id,issue)});issues=[...local.values()].sort((a,b)=>String(b.month).localeCompare(String(a.month)));const migrated=[];for(const issue of issues)if(await migrateIssueAssets(issue))migrated.push(issue);writeLocal();if(migrated.length)await Promise.allSettled(migrated.map(cloudSave));if(!active)renderLibrary()}catch(error){console.warn('Carga de SIERRA Times:',error)}}

function persist({broadcast=true,cloud=true}={}){if(!active)return;active.updatedAt=new Date().toISOString();const index=issues.findIndex(x=>x.id===active.id);if(index<0)issues.unshift(active);else issues[index]=active;writeLocal();if(broadcast&&channel)channel.postMessage({type:'issue',client:CLIENT,issue:active});if(cloud)cloudSave(active);setSaveState('Guardado');}

function schedule(){setSaveState('Guardando…');clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist(),450)}

function notify(message){typeof toast==='function'?toast(message):alert(message)}

function setSaveState(text){const node=document.getElementById('st-save');if(node)node.textContent=text}

function canEdit(){return active?.state==='working'}

function currentPage(){return active?.pages.find(x=>x.id===pageId)||active?.pages[0]}

function currentBlock(){return currentPage()?.blocks.find(x=>x.id===blockId)||null}

function initials(){const name=(typeof profile!=='undefined'&&profile?.full_name)||(typeof me!=='undefined'&&me?.email)||'Tú';return name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}

function userName(){return(typeof profile!=='undefined'&&profile?.full_name)||(typeof me!=='undefined'&&me?.email)||'Tú'}

function route(){syncModule('comunicaciones');_navLeaf='comunicaciones|_|sierra-times';sessionStorage.setItem('sierra_route','module:comunicaciones:sierra-times');leaveView();renderSidebarTree();document.getElementById('tb-section').textContent='Marketing';document.getElementById('product-controls').style.display='none'}
window.showSierraTimes=function(){route();clearSecCrumbs?.();document.getElementById('sec-title').textContent='SIERRA Times';document.getElementById('sec-sub').textContent='Edición mensual, colaboración y salidas para cada canal';load();active=null;pageId=null;blockId=null;renderLibrary();loadCloud()}

function renderLibrary(){const pg=document.getElementById('pg');pg.innerHTML=`<div class="st-library"><section class="st-library-hero"><div><p class="st-section-kicker">Publicación mensual</p><h2>Una redacción. Cuatro salidas.</h2><p>Compón SIERRA Times con lenguaje editorial y transforma la misma edición en correo continuo, PDF de lectura, pliegos de imprenta y escenas para pantallas.</p></div><div style="display:grid;align-content:end;justify-items:start;gap:10px"><button class="btn btn-primary" onclick="stCreateIssue()">${icon('plus',16)} Crear edición mensual</button><small style="color:var(--text-secondary)">Carta por página · pliego doble carta · 16:9</small></div></section><section class="st-library-card"><div class="st-panel-head"><div><h3>Ediciones</h3><small style="color:var(--text-secondary)">Las ediciones cerradas quedan disponibles solo para exportar.</small></div></div>${issues.length?`<div class="st-library-grid">${issues.map(issue=>issueCard(issue)).join('')}</div>`:`<div class="st-empty">Aún no hay ediciones. Crea la primera para comenzar.</div>`}</section></div>`}

function issueCard(issue){return`<article class="st-issue-card" onclick="stOpenIssue('${issue.id}')"><div class="st-issue-swatch"></div><div class="st-issue-card-top" style="margin-top:12px"><span class="st-status ${issue.state==='final'?'is-final':''}"><i></i>${issue.state==='final'?'Terminada':'En trabajo'}</span><span style="color:var(--text-secondary)">${icon('arrow-right',17)}</span></div><h3>${safe(monthName(issue.month))}</h3><p>${issue.pages.length} páginas · ${issue.comments.filter(c=>!c.resolved).length} comentarios abiertos</p></article>`}
window.stCreateIssue=function(){const issue=newIssue();issues.unshift(issue);active=issue;pageId=issue.pages[0].id;persist();openEditor()}
window.stOpenIssue=async function(id){active=issues.find(x=>x.id===id);if(!active)return;pageId=active.pages[0]?.id;blockId=null;setSaveState('Preparando recursos…');const migrated=await migrateIssueAssets(active);if(migrated){writeLocal();await cloudSave(active)}openEditor()}

function openEditor(){document.getElementById('sec-title').textContent=active.title;document.getElementById('sec-sub').textContent=active.state==='final'?'Edición terminada · disponible para exportar':'Edición colaborativa en curso';startCollaboration();renderEditor()}

function startCollaboration(){channel?.close();remoteChannel?.unsubscribe?.();peers=new Map();if('BroadcastChannel'in window){channel=new BroadcastChannel(`sierra-times-${active.id}`);channel.onmessage=event=>{const msg=event.data;if(!msg||msg.client===CLIENT)return;if(msg.type==='issue'&&msg.issue?.updatedAt>active.updatedAt){active=msg.issue;const i=issues.findIndex(x=>x.id===active.id);if(i>=0)issues[i]=active;persist({broadcast:false,cloud:false});renderEditor()}if(msg.type==='presence'){peers.set(msg.client,msg);renderPresence()}};channel.postMessage({type:'presence',client:CLIENT,name:userName(),initials:initials()})}cloudSubscribe()}
async function cloudSave(issue){if(typeof sb==='undefined'||typeof me==='undefined'||!me?.id)return;try{await migrateIssueAssets(issue);await sb.from('newsletter_issues').upsert({id:issue.id,issue_month:issue.month,title:issue.title,state:issue.state,payload:issue,updated_by:me.id},{onConflict:'id'})}catch(error){console.warn('Guardado en línea de SIERRA Times:',error)}}

function cloudSubscribe(){if(typeof sb==='undefined'||!active)return;try{remoteChannel=sb.channel(`newsletter:${active.id}`).on('postgres_changes',{event:'UPDATE',schema:'public',table:'newsletter_issues',filter:`id=eq.${active.id}`},payload=>{const incoming=payload.new?.payload;if(incoming&&incoming.updatedAt>active.updatedAt){active=incoming;const i=issues.findIndex(x=>x.id===active.id);if(i>=0)issues[i]=active;persist({broadcast:false,cloud:false});renderEditor()}}).on('presence',{event:'sync'},()=>{const state=remoteChannel.presenceState();Object.values(state).flat().forEach(p=>{if(p.client!==CLIENT)peers.set(p.client,p)});renderPresence()}).subscribe(status=>{if(status==='SUBSCRIBED')remoteChannel.track({client:CLIENT,name:userName(),initials:initials()})})}catch{}}

function renderPresence(){const node=document.getElementById('st-presence');if(!node)return;const others=[...peers.values()].slice(0,3);node.innerHTML=`<span class="st-avatar is-you" title="Tú">${safe(initials())}</span>${others.map(p=>`<span class="st-avatar" title="${attr(p.name||'Colaborador')}">${safe(p.initials||'ST')}</span>`).join('')}`}

function renderEditor(){const pg=document.getElementById('pg'),page=currentPage();if(!page)return;const invalid=active.pages.length%4!==0;pg.innerHTML=`<div class="st-app"><header class="st-topbar"><div class="st-topbar-main"><button class="icon-btn icon-btn-quiet" aria-label="Volver a ediciones" onclick="stBack()">${icon('arrow-left',18)}</button><div><small>SIERRA Times · ${safe(monthName(active.month))}</small><h2>${safe(active.title)}</h2></div></div><div class="st-top-actions"><span class="st-status ${active.state==='final'?'is-final':''}"><i></i>${active.state==='final'?'Terminada':'En trabajo'}</span><div class="st-presence" id="st-presence"></div><span class="st-status" id="st-save"><i></i>Guardado</span><button class="btn btn-secondary btn-sm" onclick="stSetTab('comments')">${icon('message-circle',15)} ${active.comments.filter(c=>!c.resolved).length}</button><button class="btn btn-secondary btn-sm" onclick="stExportDialog()">${icon('download',15)} Exportar</button>${canEdit()?`<button class="btn btn-primary btn-sm" onclick="stFinalize()">${icon('lock',15)} Terminar boletín</button>`:''}</div></header><div class="st-body"><aside class="st-rail"><div class="st-rail-head"><h3>Páginas</h3>${canEdit()?`<div class="st-rail-actions"><button class="icon-btn icon-btn-quiet icon-btn-sm" aria-label="Agregar página" onclick="stAddPage()">${icon('plus',15)}</button></div>`:''}</div><div class="st-page-list">${active.pages.map((p,i)=>pageThumb(p,i)).join('')}</div><div class="st-page-count ${invalid?'is-warning':''}"><strong>${active.pages.length} páginas</strong><br>${invalid?'Faltan páginas para completar un cuadernillo.':'Lista para cuadernillo: múltiplo de 4.'}${invalid&&canEdit()?`<button class="btn btn-secondary btn-sm" onclick="stCompleteBooklet()">Completar automáticamente</button>`:''}</div></aside><main class="st-stage"><div class="st-stage-head"><span>Carta · 8.5 × 11 in · página ${active.pages.indexOf(page)+1}</span><div class="st-stage-tools"><button class="btn btn-ghost btn-sm" onclick="stOpenPreview('full')">${icon('book-open',14)} Vista completa</button><button class="btn btn-ghost btn-sm" onclick="stOpenPreview('email')">Correo</button><button class="btn btn-ghost btn-sm" onclick="stOpenPreview('screen')">Pantalla</button></div></div>${pageHtml(page,active.pages.indexOf(page),'print')}</main><aside class="st-inspector">${inspectorHtml()}</aside></div></div>`;renderPresence();queueMicrotask(()=>{renderQrs();hydrateAssets(pg)})}

function pageThumb(p,i){const count=p.layout==='cover'?`${featuredStories().length} notas destacadas`:['new-hires','birthdays-current','birthdays-next'].includes(p.kind)?`${p.people?.length||0} personas`:`${p.blocks.length} notas`;return`<button class="st-page-thumb ${p.id===pageId?'is-active':''}" onclick="stPickPage('${p.id}')"><b>${i+1}</b><span class="st-thumb-sheet" style="--thumb-accent:${COLORS[p.accent]||COLORS.orange}"></span><span><b>${safe(p.title)}</b><small>${p.mandatory?'Obligatoria · ':''}${count}</small></span></button>`}

function mastheadHtml(page){if(page.layout==='cover')return`<header class="st-cover-masthead" data-required-cover-masthead="true" aria-label="Encabezado oficial de portada de The Sierra Times"><div class="st-cover-double-rule" aria-hidden="true"></div><div class="st-cover-name">The Sierra Times</div><div class="st-cover-rule" aria-hidden="true"></div><div class="st-cover-date">${safe(monthName(active.month))}</div><div class="st-cover-rule" aria-hidden="true"></div></header>`;if(!active.settings.showMasthead)return'';return`<header class="st-masthead"><div class="st-masthead-logo" aria-label="The Sierra Times">The Sierra Times</div><div class="st-masthead-meta">${safe(monthName(active.month))}<span class="st-page-meta"><br>Edición ${String(active.version).padStart(2,'0')}</span></div></header>`}

function featuredStories(){const stories=[];(active?.pages||[]).forEach((page,pageIndex)=>{if(page.layout==='cover')return;(page.blocks||[]).filter(block=>block.type==='story'&&block.showOnCover).forEach(story=>{const photo=(story.items||[]).find(item=>item.type==='photo'),order=stories.length,summary=String(story.deck||story.body||'').replace(/\s+/g,' ').trim().slice(0,190);stories.push({...story,id:`cover-${story.id}`,coverSourcePageId:page.id,coverSourceStoryId:story.id,span:order%2===0?8:4,deck:summary,pageRef:`PÁGINA ${pageIndex+1}`,items:photo?[{...photo,height:order===0?'medium':'short'}]:[]})})});return stories.slice(0,4)}

function coverColumnsHtml(page){const blocks=featuredStories();if(!blocks.length)return`<div class="st-cover-empty"><div><strong>Portada pendiente</strong><span>Selecciona una nota interior y activa “Mostrar en portada”.</span></div></div>`;const main=[],side=[];blocks.forEach((block,index)=>{(index%2===0?main:side).push(blockHtml(block,{...page,blocks}))});const single=!side.length;return`<div class="st-cover-columns ${single?'is-single':''}"><div class="st-cover-column st-cover-main">${main.join('')}</div>${single?'':`<div class="st-cover-column st-cover-side">${side.join('')}</div>`}</div>`}

function pageHtml(page,index,channelName='print',screen=false){const accent=COLORS[page.accent]||COLORS.orange,special=page.kind&&!['cover','editorial'].includes(page.kind),content=special?specialPageHtml(page):page.layout==='cover'?coverColumnsHtml(page):`<div class="st-sheet-grid">${page.blocks.map(block=>blockHtml(block,page)).join('')}</div>`,footer=String(page.footerText||'').trim();return`<article class="st-sheet ${screen?'st-screen-sheet':''}" data-page="${page.id}" data-layout="${page.layout}" data-kind="${page.kind||'editorial'}" data-channel="${channelName}" style="--page-accent:${accent}">${mastheadHtml(page)}${content}${footer?`<footer class="st-folio"><span>${safe(footer)}</span><b>${index+1}</b></footer>`:''}</article>`}

function specialPageHtml(page){if(page.kind==='credits-policy'){const credits=page.credits||{},rows=[['Edición y coordinación',credits.direction],['Talento Humano',credits.talent],['Diseño editorial',credits.design],['Textos y colaboración',credits.texts],['Fotografía',credits.photography],['Contacto',credits.contact]].filter(([,value])=>String(value||'').trim());return`<div class="st-mandatory-page st-credits-page"><header><p class="st-special-label">Quiénes hicieron esta edición</p><h1>Créditos</h1><p>Una publicación construida entre equipos SIERRA.</p></header><div class="st-credits-list">${rows.map(([label,value],index)=>`<section><span>${String(index+1).padStart(2,'0')}</span><div><small>${safe(label)}</small><strong>${safe(value)}</strong></div></section>`).join('')}</div><footer><div class="st-credit-wordmark">The Sierra Times</div><span>${safe(monthName(active.month))}</span></footer></div>`}if(page.kind==='activities'){return`<div class="st-mandatory-page st-activities-page"><header class="st-special-header"><p class="st-special-label">Agenda SIERRA</p><h1>Actividades del mes</h1><p>Fechas, encuentros y momentos para participar.</p></header>${page.activities?.length?`<div class="st-activity-list">${page.activities.map((activity,index)=>`<article style="--activity-accent:${COLORS[activity.accent]||COLORS.teal}"><time><b>${safe(activity.date||String(index+1).padStart(2,'0'))}</b><span>${safe(activity.time||'')}</span></time><div><p>${safe(activity.category||'Actividad')}</p><h2>${safe(activity.title||'Actividad SIERRA')}</h2>${activity.description?`<span>${safe(activity.description)}</span>`:''}<small>${safe([activity.location,activity.country].filter(Boolean).join(' · '))}</small></div></article>`).join('')}</div>`:`<div class="st-roster-empty">Agrega las actividades confirmadas de este mes.</div>`}</div>`}const current=page.kind==='birthdays-current',next=page.kind==='birthdays-next',label=page.kind==='new-hires'?'Nuevos ingresos':next?'Próximos cumpleaños':'Cumpleaños del mes',intro=page.kind==='new-hires'?'Personas que se integran a nuestros equipos.':next?'Fechas del siguiente mes para anticipar la celebración.':'Celebramos a quienes cumplen años este mes.',dense=(page.people?.length||0)>24;return`<div class="st-mandatory-page st-people-page ${next?'is-compact':''} ${dense?'is-dense':''}"><header class="st-special-header"><p class="st-special-label">${safe(label)}</p><h1>${safe(label)}</h1><p>${safe(intro)}</p></header>${page.people?.length?`<div class="st-people-grid">${page.people.map(person=>personCardHtml(person,{photo:!next,birthday:current||next})).join('')}</div>`:`<div class="st-roster-empty">Importa el Excel para componer esta sección.</div>`}</div>`}

function personCardHtml(person,{photo=true,birthday=false}={}){return`<article class="st-person-card ${photo?'':'is-row'}">${photo?`<div class="st-person-photo">${person.photo?`<img src="${attr(person.photo)}" alt="${attr(person.name||'Colaborador')}">`:`<span>${safe((person.name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2))}</span>`}</div>`:''}<div><h3>${safe(person.name||'Nombre pendiente')}</h3>${birthday&&person.date?`<p class="st-person-date">${safe(person.date)}</p>`:''}${person.role?`<p>${safe(person.role)}</p>`:''}<small>${safe([person.department,person.company,person.country].filter(Boolean).join(' · '))}</small></div></article>`}

function toolButtons(block){if(!canEdit()||block.coverSourcePageId)return'';return`<span class="st-block-tools"><button aria-label="Editar nota" title="Editar nota" onclick="event.stopPropagation();stPickBlock('${block.id}')">${icon('pencil',13)}</button><button aria-label="Duplicar nota" title="Duplicar nota" onclick="event.stopPropagation();stDuplicateBlock('${block.id}')">${icon('copy',13)}</button><button aria-label="Eliminar nota" title="Eliminar nota" onclick="event.stopPropagation();stDeleteBlock('${block.id}')">${icon('trash',13)}</button></span>`}

function availableOrgCharts(){try{return(typeof _commsDrafts==='undefined'?[]:_commsDrafts).flatMap(draft=>(draft.blocks||[]).filter(block=>block.type==='orgchart').map(block=>({key:`${draft.id}::${block.id}`,label:`${draft.subject||draft.title||draft.folio||'Memo'} · ${block.title||'Organigrama'}`,chart:block})))}catch{return[]}}

function storyOrgChartHtml(item){const chart=item.chart,people=chart?.people||[];if(!people.length)return`<div class="st-org-empty">${icon('sitemap',22)}<span>Elige un organigrama guardado en Memos.</span></div>`;return`<section class="st-story-org"><header><p class="st-section-kicker">Organigrama</p><h3>${safe(chart.title||'Estructura organizacional')}</h3></header><div class="st-org-grid">${people.map(person=>`<article>${person.photo?`<img src="${attr(person.photo)}" alt="${attr(person.name||'Persona')}">`:`<span>${safe((person.name||'?').split(/\s+/).map(part=>part[0]).join('').slice(0,2))}</span>`}<div><strong>${safe(person.name||'Nombre')}</strong><small>${safe(person.role||'Puesto')}</small><em>${safe(person.department||'')}</em></div></article>`).join('')}</div></section>`}

function storyItemHtml(item,index){if(item.type==='photo'){const height=['short','medium','tall'].includes(item.height)?item.height:'medium',x=Math.max(0,Math.min(100,Number(item.x??50))),y=Math.max(0,Math.min(100,Number(item.y??50))),zoom=Math.max(100,Math.min(180,Number(item.zoom||100))),editable=canEdit(),interaction=editable?` role="button" tabindex="0" aria-label="Editar encuadre de esta fotografía" onclick="stEditStoryPhoto(event)" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();stEditStoryPhoto(event)}"`:'';return`<figure class="st-story-media ${editable?'is-editable':''}"${interaction} data-item="${attr(item.id)}" data-height="${height}" style="--photo-x:${x}%;--photo-y:${y}%;--photo-zoom:${zoom/100}">${item.src?`<img src="${attr(item.src)}" alt="${attr(item.alt||item.caption||'Fotografía editorial')}">`:`<div class="st-photo-placeholder">${icon('photo',24)}<span>Fotografía de la nota</span></div>`}${item.caption?`<figcaption>${safe(item.caption)}</figcaption>`:''}</figure>`}if(item.type==='orgchart')return storyOrgChartHtml(item);if(item.type==='link')return`<a class="st-story-link" href="${attr(item.url||'#')}" target="_blank" rel="noopener">${safe(item.label||item.url||'Abrir enlace')} ${icon('external-link',13)}</a>`;if(item.type==='cta')return`<aside class="st-story-action"><div><strong>${safe(item.title||'Conoce más')}</strong><p>${safe(item.body||'')}</p>${item.url?`<span class="st-url">${safe(item.url)}</span>`:''}</div><canvas class="st-qr" data-st-qr="${attr(item.url||'')}"></canvas></aside>`;if(item.type==='contact')return`<aside class="st-story-contact">${item.photo?`<img src="${attr(item.photo)}" alt="${attr(item.name||'Contacto')}">`:`<span class="st-contact-fallback">${icon('user',18)}</span>`}<div><strong>${safe(item.name||'Contacto')}</strong><p>${safe([item.role,item.department].filter(Boolean).join(' · '))}</p><small>${safe([item.email,item.country].filter(Boolean).join(' · '))}</small></div></aside>`;return''}

function blockHtml(b,page=currentPage()){const cls=`st-block st-${b.type} st-span-${b.span||12} ${b.id===blockId?'is-selected':''}`,style=`--block-accent:${COLORS[b.accent]||COLORS.orange};--photo-x:${b.x??50}%;--photo-y:${b.y??50}%;--photo-zoom:${(b.zoom||100)/100}`,click=b.coverSourcePageId?`onclick="stOpenCoverSource('${b.coverSourcePageId}','${b.coverSourceStoryId}')"`:`onclick="stPickBlock('${b.id}')"`;if(b.type==='story'){const lead=page?.blocks?.filter(block=>block.type==='story')[0]?.id===b.id,items=(b.items||[]).map(storyItemHtml).join('');if(page?.layout==='cover')return`<section class="${cls} st-cover-story ${lead?'is-lead':''}" style="${style}" ${click} title="Abrir nota interior">${toolButtons(b)}<p class="st-section-kicker">${safe(b.kicker||'Sección')}</p><h1 class="st-title ${lead?'is-hero':''}">${safe(b.title||'Título de la historia')}</h1>${b.deck?`<p class="st-deck">${safe(b.deck)}</p>`:''}${items?`<div class="st-story-items">${items}</div>`:''}<div class="st-cover-page-ref">${safe(b.pageRef||'PÁGINA 3')}</div></section>`;return`<section class="${cls}" style="${style};--story-columns:${b.columns||1}" ${click}>${toolButtons(b)}<p class="st-section-kicker">${safe(b.kicker||'Sección')}</p><h1 class="st-title">${safe(b.title||'Título de la historia')}</h1>${b.deck?`<p class="st-deck">${safe(b.deck)}</p>`:''}${b.author?`<div class="st-byline">Por ${safe(b.author)}${b.country||b.site?` · ${safe([b.country,b.site].filter(Boolean).join(' / '))}`:''}</div>`:''}<p>${safe(b.body||'Escribe el contenido de esta nota.').replace(/\n/g,'<br>')}</p>${items?`<div class="st-story-items">${items}</div>`:''}</section>`}if(b.type==='photo')return`<figure class="${cls}" style="${style}" ${click}>${toolButtons(b)}${b.src?`<img src="${attr(b.src)}" alt="${attr(b.alt||b.caption||'Fotografía editorial')}">`:`<div class="st-photo-placeholder">${icon('photo',26)}<span>Fotografía heredada</span></div>`}${b.caption?`<figcaption class="st-caption">${safe(b.caption)}</figcaption>`:''}</figure>`;if(b.type==='quote')return`<aside class="${cls}" style="${style}" ${click}>${toolButtons(b)}<blockquote>“${safe(b.text||'Una frase puede abrir una pausa y darle ritmo a la edición.')}”</blockquote>${b.author?`<cite>${safe(b.author)}</cite>`:''}</aside>`;if(b.type==='insert')return`<aside class="${cls}" style="${style}" ${click}>${toolButtons(b)}<p class="st-section-kicker">${safe(b.kicker||'Anuncio')}</p><h2>${safe(b.title||'Inserto editorial')}</h2><p>${safe(b.body||'Información breve y destacada.')}</p></aside>`;if(b.type==='cta')return`<aside class="${cls}" style="${style}" ${click}>${toolButtons(b)}<div><p class="st-section-kicker">${safe(b.kicker||'Participa')}</p><h2>${safe(b.title||'Conoce más')}</h2><p>${safe(b.body||'Escanea el código o abre el enlace.')}</p>${b.url?`<a href="${attr(b.url)}">${safe(b.url)}</a>`:''}</div><canvas class="st-qr" data-st-qr="${attr(b.url||'')}"></canvas></aside>`;if(b.type==='contact')return`<aside class="${cls}" style="${style}" ${click}>${toolButtons(b)}<span class="st-contact-mark"></span><div><h3>${safe(b.title||'Contacto')}</h3><p>${safe(b.name||'Nombre y cargo')}<br>${safe(b.email||'correo@sierra.com')}${b.phone?` · ${safe(b.phone)}`:''}</p></div></aside>`;return`<aside class="${cls} ${b.internal?'is-internal':''}" style="${style}" ${click}>${toolButtons(b)}${safe(b.body||'Nota editorial')}</aside>`}

function inspectorHtml(){return`<div class="st-panel-tabs"><button class="${tab==='design'?'is-active':''}" onclick="stSetTab('design')">Diseño</button><button class="${tab==='assets'?'is-active':''}" onclick="stSetTab('assets')">Recursos</button><button class="${tab==='comments'?'is-active':''}" onclick="stSetTab('comments')">Comentarios</button></div>${designPanel()}${assetsPanel()}${commentsPanel()}`}

function designPanel(){const b=currentBlock(),page=currentPage();return`<section class="st-panel" ${tab==='design'?'':'hidden'}>${!canEdit()?`<div class="st-final-lock">${icon('lock',17)}<span>Esta edición está terminada. Su contenido no puede modificarse; las exportaciones siguen disponibles.</span></div>`:b?blockForm(b):pageForm(page)}</section>`}

function pageForm(page){const head=`<div class="st-panel-head"><div><h3>${safe(page.title)}</h3><small style="color:var(--text-secondary)">${page.mandatory?'Sección obligatoria':'Composición de la página'}</small></div>${page.mandatory?`<span class="st-required-badge">Fija</span>`:''}</div>`;if(page.kind==='credits-policy')return`${head}<div class="st-form"><p class="st-editor-help">Todos los créditos son editables. Los campos vacíos no aparecen en la edición final.</p>${pageField('Edición y coordinación','credits.direction',page.credits?.direction,{area:true})}${pageField('Talento Humano','credits.talent',page.credits?.talent,{area:true})}${pageField('Diseño editorial','credits.design',page.credits?.design)}${pageField('Textos y colaboración','credits.texts',page.credits?.texts)}${pageField('Fotografía','credits.photography',page.credits?.photography,{area:true})}${pageField('Contacto editorial','credits.contact',page.credits?.contact)}${footerField(page)}</div>`;if(page.kind==='activities')return`${head}<div class="st-form"><p class="st-editor-help">Agrega únicamente actividades confirmadas. Cada una puede usar un acento funcional distinto.</p><button class="btn btn-secondary" onclick="stActivityAdd()">${icon('plus',15)} Agregar actividad</button>${(page.activities||[]).map(activityEditor).join('')}${!page.activities?.length?`<div class="st-empty">Aún no hay actividades.</div>`:''}${footerField(page)}</div>`;if(['new-hires','birthdays-current','birthdays-next'].includes(page.kind))return`${head}<div class="st-form"><p class="st-editor-help">Importa los datos desde Excel o CSV. Las fotos se suben directamente o se asignan desde Recursos.</p><label class="st-upload">${icon('file-spreadsheet',20)||icon('upload',20)}<span>Importar Excel o CSV</span><input type="file" accept=".xlsx,.xls,.csv" onchange="stRosterImport(this)"></label><button class="btn btn-ghost btn-sm" onclick="stRosterTemplate()">${icon('download',14)} Descargar plantilla CSV</button><div class="st-roster-summary"><strong>${page.people?.length||0}</strong><span>personas importadas</span></div>${(page.people||[]).slice(0,20).map((person,index)=>personEditor(person,index,page.kind)).join('')}${page.people?.length>20?`<small>Se muestran 20 de ${page.people.length}. Todas se incluyen en la composición.</small>`:''}${footerField(page)}</div>`;return`${head}<div class="st-form"><div class="st-field"><label>Título interno de página</label><input value="${attr(page.title)}" oninput="stPageSet('title',this.value)"></div><div class="st-field"><label>Color editorial</label>${colorGrid(page.accent,"stPageSet('accent',this.dataset.color)")}</div><div class="st-field"><label>Contenido</label><div class="st-block-palette">${addButton('story','news','Nueva nota')}</div><small>Cada nota puede contener varias fotos, enlaces, CTA, contactos y organigramas.</small></div>${footerField(page)}${page.mandatory?'':`<button class="btn btn-ghost" onclick="stDeletePage()">${icon('trash',15)} Eliminar esta página</button>`}</div>`}

const editorialPageForm=pageForm;
pageForm=function(page){
  if(page.layout!=='cover')return editorialPageForm(page);
  const selected=featuredStories();
  const head=`<div class="st-panel-head"><div><h3>Portada</h3><small style="color:var(--text-secondary)">Composición derivada</small></div><span class="st-required-badge">Fija</span></div>`;
  return`${head}<div class="st-form"><p class="st-editor-help"><strong>La portada se arma al final.</strong><br>Abre una nota interior y activa “Mostrar en portada”. Su titular, resumen, primera fotografía y número de página se mantendrán sincronizados.</p><div class="st-cover-source-head"><span>Notas destacadas</span><b>${selected.length}/4</b></div>${selected.length?`<div class="st-cover-source-list">${selected.map(story=>`<button onclick="stOpenCoverSource('${story.coverSourcePageId}','${story.coverSourceStoryId}')"><span>${safe(story.kicker||'Nota interior')}</span><strong>${safe(story.title||'Sin título')}</strong><small>${safe(story.pageRef)}</small></button>`).join('')}</div>`:`<div class="st-empty">Aún no has elegido notas para la portada.</div>`}</div>`
};
function activityEditor(activity,index){return`<article class="st-story-item"><header><b>${icon('calendar',14)} Actividad ${index+1}</b><button class="icon-btn icon-btn-quiet icon-btn-sm" aria-label="Quitar actividad" onclick="stActivityRemove(${index})">${icon('trash',14)}</button></header>${itemInput(index,'Título','title',activity.title,'text','activity')}${itemInput(index,'Fecha','date',activity.date,'text','activity')}${itemInput(index,'Horario','time',activity.time,'text','activity')}${itemInput(index,'Lugar','location',activity.location,'text','activity')}${itemInput(index,'País','country',activity.country,'text','activity')}${itemInput(index,'Descripción','description',activity.description,'text','activity')}<div class="st-field"><label>Color de identificación</label>${colorGrid(activity.accent||'teal',`stActivitySet(${index},'accent',this.dataset.color)`)}</div></article>`}

function pageField(label,key,value,{area=false}={}){return`<div class="st-field"><label>${label}</label>${area?`<textarea oninput="stPageNestedSet('${key}',this.value)">${safe(value||'')}</textarea>`:`<input value="${attr(value||'')}" oninput="stPageNestedSet('${key}',this.value)">`}</div>`}

function footerField(page){return`<div class="st-field"><label>Pie de página opcional</label><input value="${attr(page.footerText||'')}" placeholder="Déjalo vacío para que no aparezca" oninput="stPageSet('footerText',this.value)"><small>Si está vacío, no se exporta ni reserva espacio.</small></div>`}

function personEditor(person,index,kind){const assets=active.assets||[];return`<article class="st-roster-row"><label class="st-roster-photo" title="Subir foto directamente">${person.photo?`<img src="${attr(person.photo)}" alt="">`:icon('camera',16)}<input type="file" accept="image/*" onchange="stRosterPhoto(${index},this)"></label><div><input value="${attr(person.name||'')}" placeholder="Nombre" oninput="stRosterSet(${index},'name',this.value)"><input value="${attr(kind==='birthdays-current'||kind==='birthdays-next'?person.date:person.role||'')}" placeholder="${kind.startsWith('birthdays')?'Fecha':'Puesto'}" oninput="stRosterSet(${index},'${kind.startsWith('birthdays')?'date':'role'}',this.value)">${assets.length?`<select aria-label="Asignar foto desde Recursos" onchange="stRosterAsset(${index},this.value)"><option value="">Elegir de Recursos…</option>${assets.map(asset=>`<option value="${asset.id}">${safe(asset.name)}</option>`).join('')}</select>`:''}</div><button class="icon-btn icon-btn-quiet icon-btn-sm" aria-label="Quitar persona" onclick="stRosterRemove(${index})">${icon('trash',14)}</button></article>`}

function addButton(type,ico,label){return`<button class="st-block-add" data-type="${type}" onclick="stAddBlock('${type}')"><span>${icon(ico,16)}</span><b>${label}</b></button>`}

function colorGrid(value,handler){return`<div class="st-color-grid">${Object.entries(COLORS).map(([name,color])=>`<button class="st-color ${value===name?'is-active':''}" style="background:${color}" data-color="${name}" aria-label="${name}" onclick="${handler}"></button>`).join('')}</div>`}

function commonFields(b){return`<div class="st-field"><label>Color de énfasis</label>${colorGrid(b.accent||'orange',"stBlockSet('accent',this.dataset.color)")}</div><div class="st-field"><label>Ancho</label><div style="display:flex;gap:5px">${[4,6,8,12].map(n=>`<button class="btn ${b.span===n?'btn-secondary':'btn-ghost'} btn-sm" onclick="stBlockSet('span',${n})">${n}/12</button>`).join('')}</div></div>`}

function field(label,key,value,{area=false,type='text',hint=''}={}){return`<div class="st-field"><label>${label}</label>${area?`<textarea oninput="stBlockSet('${key}',this.value)">${safe(value||'')}</textarea>`:`<input type="${type}" value="${attr(value||'')}" oninput="stBlockSet('${key}',this.value)">`}${hint?`<small>${hint}</small>`:''}</div>`}

function blockForm(b){let fields='';if(b.type==='story')fields=currentPage()?.layout==='cover'?field('Sección','kicker',b.kicker)+field('Titular','title',b.title,{area:true})+field('Bajada','deck',b.deck,{area:true})+field('Página interior','pageRef',b.pageRef,{hint:'Ej. PÁGINA 3'}):field('Sección','kicker',b.kicker)+field('Titular','title',b.title,{area:true})+field('Bajada','deck',b.deck,{area:true})+field('Texto','body',b.body,{area:true})+field('Autor','author',b.author)+`<div class="st-field-row">${field('País','country',b.country)}${field('Sede / empresa','site',b.site)}</div>`;if(b.type==='photo')fields=`<label class="st-upload">${icon('upload',20)}<span>Seleccionar fotografía</span><input type="file" accept="image/*" onchange="stPhotoFile(this)"></label>`+field('Pie de foto','caption',b.caption,{area:true})+field('Descripción accesible','alt',b.alt)+`<div class="st-field-row">${rangeField('Horizontal','x',b.x??50,0,100)}${rangeField('Vertical','y',b.y??50,0,100)}</div>${rangeField('Zoom','zoom',b.zoom||100,100,220)}`;if(b.type==='quote')fields=field('Cita','text',b.text,{area:true})+field('Autor o fuente','author',b.author);if(b.type==='insert')fields=field('Etiqueta','kicker',b.kicker)+field('Título','title',b.title,{area:true})+field('Texto','body',b.body,{area:true});if(b.type==='cta')fields=field('Etiqueta','kicker',b.kicker)+field('Título','title',b.title)+field('Texto','body',b.body,{area:true})+field('Enlace','url',b.url,{type:'url',hint:'La dirección completa siempre permanece visible en la pieza.'})+`<button class="btn btn-secondary" onclick="stGenerateQr()">${icon('qr-code',16)} Actualizar código QR</button>`;if(b.type==='contact')fields=field('Título','title',b.title)+field('Nombre y cargo','name',b.name)+field('Correo','email',b.email,{type:'email'})+field('Teléfono','phone',b.phone);if(b.type==='note')fields=field('Nota','body',b.body,{area:true})+`<label class="st-switch"><input type="checkbox" ${b.internal?'checked':''} onchange="stBlockSet('internal',this.checked)"> Solo para el equipo; no exportar</label>`;return`<button class="btn btn-ghost btn-sm" onclick="stClearBlock()">${icon('arrow-left',14)} Página</button><div class="st-panel-head" style="margin-top:12px"><div><h3>${blockLabels[b.type]}</h3><small style="color:var(--text-secondary)">Unidad editorial</small></div></div><div class="st-form">${fields}${b.type==='story'?storyItemsEditor(b):''}${commonFields(b)}<button class="btn btn-ghost" onclick="stDeleteBlock('${b.id}')">${icon('trash',15)} Eliminar nota</button></div>`}

const editorialBlockForm=blockForm;
blockForm=function(block){
  const html=editorialBlockForm(block);
  if(block.type!=='story'||currentPage()?.layout==='cover')return html;
  const toggle=`<label class="st-switch st-cover-toggle"><input type="checkbox" ${block.showOnCover?'checked':''} onchange="stBlockSet('showOnCover',this.checked)"><span><strong>Mostrar en portada</strong><small>Usará este titular, resumen, primera fotografía y página.</small></span></label>`;
  return html.replace('<div class="st-form">',`<div class="st-form">${toggle}`)
};
function storyItemsEditor(story){return`<section class="st-story-builder"><div><strong>Contenido de la nota</strong><small>Puedes combinar y repetir recursos dentro de la misma historia.</small></div>${(story.items||[]).map((item,index)=>storyItemEditor(item,index)).join('')}<div class="st-story-add"><button onclick="stStoryAdd('photo')">${icon('photo',15)} Otra foto</button><button onclick="stStoryAdd('link')">${icon('external-link',15)} Enlace</button><button onclick="stStoryAdd('cta')">${icon('qr-code',15)} CTA</button><button onclick="stStoryAdd('contact')">${icon('user',15)} Contacto</button><button onclick="stStoryAdd('orgchart')">${icon('sitemap',15)} Organigrama</button></div></section>`}

function itemInput(index,label,key,value,type='text',context='story'){const handler=context==='activity'?`stActivitySet(${index},'${key}',this.value)`:`stStoryItemSet(${index},'${key}',this.value)`;return`<label><span>${label}</span><input type="${type}" value="${attr(value||'')}" oninput="${handler}"></label>`}

function storyPhotoRange(index,label,key,value,min,max){return`<label class="st-photo-range"><span>${label}<output>${value}%</output></span><input type="range" min="${min}" max="${max}" value="${value}" oninput="this.previousElementSibling.querySelector('output').value=this.value+'%';stStoryItemSet(${index},'${key}',Number(this.value))"></label>`}

function storyItemEditor(item,index){const remove=`<button class="icon-btn icon-btn-quiet icon-btn-sm" aria-label="Quitar ${blockLabels[item.type]||item.type}" onclick="stStoryItemDelete(${index})">${icon('trash',14)}</button>`;if(item.type==='photo'){const height=['short','medium','tall'].includes(item.height)?item.height:'medium',x=Math.max(0,Math.min(100,Number(item.x??50))),y=Math.max(0,Math.min(100,Number(item.y??50))),zoom=Math.max(100,Math.min(180,Number(item.zoom||100)));return`<article class="st-story-item st-photo-editor" data-story-item="${attr(item.id)}"><header><b>${icon('photo',14)} Encuadre de fotografía</b>${remove}</header><label class="st-upload st-upload-compact">${item.src?`<img src="${attr(item.src)}" alt="">`:icon('upload',16)}<span>${item.src?'Cambiar foto':'Seleccionar foto'}</span><input type="file" accept="image/*" onchange="stStoryItemPhoto(${index},this)"></label><label><span>Altura segura</span><select onchange="stStoryItemSet(${index},'height',this.value)">${[['short','Baja'],['medium','Media'],['tall','Alta']].map(([value,label])=>`<option value="${value}" ${height===value?'selected':''}>${label}</option>`).join('')}</select></label>${storyPhotoRange(index,'Posición horizontal','x',x,0,100)}${storyPhotoRange(index,'Posición vertical','y',y,0,100)}${storyPhotoRange(index,'Zoom','zoom',zoom,100,180)}<button class="btn btn-ghost btn-sm" onclick="stStoryPhotoReset(${index})">${icon('refresh-cw',14)} Centrar encuadre</button>${itemInput(index,'Pie de foto','caption',item.caption)}</article>`}if(item.type==='orgchart'){const charts=availableOrgCharts();return`<article class="st-story-item"><header><b>${icon('sitemap',14)} Organigrama</b>${remove}</header><label><span>Organigrama guardado en Memos</span><select onchange="stStoryOrgSelect(${index},this.value)"><option value="">Seleccionar…</option>${charts.map(option=>`<option value="${attr(option.key)}">${safe(option.label)}</option>`).join('')}</select></label>${charts.length?'':`<small>Crea y guarda primero el organigrama desde Memos; después aparecerá aquí.</small>`}</article>`}if(item.type==='link')return`<article class="st-story-item"><header><b>${icon('external-link',14)} Enlace</b>${remove}</header>${itemInput(index,'Texto','label',item.label)}${itemInput(index,'Dirección','url',item.url,'url')}</article>`;if(item.type==='cta')return`<article class="st-story-item"><header><b>${icon('qr-code',14)} CTA editorial</b>${remove}</header>${itemInput(index,'Título','title',item.title)}${itemInput(index,'Texto','body',item.body)}${itemInput(index,'Dirección','url',item.url,'url')}</article>`;return`<article class="st-story-item"><header><b>${icon('user',14)} Contacto</b>${remove}</header><label class="st-upload st-upload-compact">${item.photo?`<img src="${attr(item.photo)}" alt="">`:icon('camera',16)}<span>Foto</span><input type="file" accept="image/*" onchange="stStoryItemPhoto(${index},this)"></label>${itemInput(index,'Nombre','name',item.name)}${itemInput(index,'Puesto','role',item.role)}${itemInput(index,'Correo','email',item.email,'email')}${itemInput(index,'País','country',item.country)}${itemInput(index,'Departamento','department',item.department)}</article>`}

function rangeField(label,key,value,min,max){return`<div class="st-field"><label>${label} · <output>${value}%</output></label><input type="range" min="${min}" max="${max}" value="${value}" oninput="this.previousElementSibling.querySelector('output').value=this.value+'%';stBlockSet('${key}',Number(this.value))"></div>`}

function assetsPanel(){return`<section class="st-panel" ${tab==='assets'?'':'hidden'}><div class="st-panel-head"><div><h3>Biblioteca visual</h3><small style="color:var(--text-secondary)">Los originales se conservan; el encuadre es reversible.</small></div></div>${canEdit()?`<label class="st-upload">${icon('upload',20)}<span>Subir fotografías</span><input type="file" accept="image/*" multiple onchange="stAssetFiles(this)"></label>`:''}<div class="st-assets" style="margin-top:10px">${active.assets.map(a=>`<div class="st-asset" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${a.id}')" onclick="stUseAsset('${a.id}')"><img src="${attr(a.src)}" alt="${attr(a.name)}">${canEdit()?`<button aria-label="Quitar recurso" onclick="event.stopPropagation();stDeleteAsset('${a.id}')">×</button>`:''}</div>`).join('')}</div>${!active.assets.length?`<div class="st-empty">Sube fotografías una vez y reutilízalas en cualquier página.</div>`:''}</section>`}

function commentsPanel(){const target=blockId?`Elemento · ${blockLabels[currentBlock()?.type]||''}`:`Página ${active.pages.findIndex(p=>p.id===pageId)+1}`;return`<section class="st-panel" ${tab==='comments'?'':'hidden'}><div class="st-panel-head"><div><h3>Comentarios</h3><small style="color:var(--text-secondary)">Anclados a página o elemento</small></div></div>${canEdit()?`<div class="st-form"><div class="st-field"><label>${safe(target)}</label><textarea id="st-comment-input" placeholder="Escribe un comentario o menciona a alguien con @"></textarea></div><button class="btn btn-secondary" onclick="stAddComment()">${icon('send',15)} Comentar</button></div>`:''}<div class="st-comment-list" style="margin-top:14px">${active.comments.map(commentHtml).join('')}</div>${!active.comments.length?`<div class="st-empty">Las observaciones del equipo aparecerán aquí.</div>`:''}</section>`}

function commentHtml(c){return`<article class="st-comment ${c.resolved?'is-resolved':''}"><div class="st-comment-head"><b>${safe(c.author)}</b><span>${new Date(c.createdAt).toLocaleDateString('es-GT')}</span></div><p>${safe(c.text)}</p><small>${c.blockId?blockLabels[active.pages.flatMap(p=>p.blocks).find(b=>b.id===c.blockId)?.type]||'Elemento':`Página ${active.pages.findIndex(p=>p.id===c.pageId)+1}`}</small>${canEdit()?`<div class="st-comment-actions"><button class="btn btn-ghost btn-sm" onclick="stResolveComment('${c.id}')">${c.resolved?'Reabrir':'Resolver'}</button></div>`:''}</article>`}
window.stOpenCoverSource=function(sourcePageId,storyId){pageId=sourcePageId;blockId=storyId;tab='design';renderEditor()};
function setEditorialBlockValue(key,value){
  const block=currentBlock();
  if(!canEdit()||!block)return;
  if(key==='showOnCover'&&value){
    const selected=(active.pages||[]).flatMap(page=>(page.blocks||[]).filter(story=>story.type==='story'&&story.showOnCover&&story.id!==block.id));
    if(selected.length>=4){notify('La portada admite hasta cuatro notas. Quita una antes de agregar otra.');renderEditor();return}
  }
  block[key]=value;schedule();renderEditor()
}
window.stBack=function(){channel?.close();remoteChannel?.unsubscribe?.();active=null;renderLibrary()};window.stSetTab=function(value){tab=value;renderEditor()};window.stPickPage=function(id){pageId=id;blockId=null;renderEditor()};window.stPickBlock=function(id){blockId=id;tab='design';renderEditor()};window.stClearBlock=function(){blockId=null;renderEditor()};
function refreshStage(){const stage=document.querySelector('.st-stage'),sheet=stage?.querySelector(':scope > .st-sheet'),page=currentPage();if(!sheet||!page)return;sheet.outerHTML=pageHtml(page,active.pages.indexOf(page),'print');queueMicrotask(()=>{renderQrs();hydrateAssets(stage)})}
window.stPageSet=function(key,value){if(!canEdit())return;currentPage()[key]=value;schedule();refreshStage()};window.stPageNestedSet=function(path,value){if(!canEdit())return;const keys=path.split('.'),last=keys.pop();let target=currentPage();keys.forEach(key=>target=target[key]||(target[key]={}));target[last]=value;schedule();refreshStage()};window.stBlockSet=function(key,value){if(!canEdit()||!currentBlock())return;currentBlock()[key]=value;schedule();refreshStage()};
window.stBlockSet=setEditorialBlockValue;
window.stActivityAdd=function(){if(!canEdit())return;currentPage().activities=currentPage().activities||[];currentPage().activities.push({id:uid(),title:'Nueva actividad',date:'',time:'',location:'',country:'',description:'',accent:'teal'});schedule();renderEditor()};window.stActivitySet=function(index,key,value){const activity=currentPage()?.activities?.[index];if(!canEdit()||!activity)return;activity[key]=value;schedule();refreshStage()};window.stActivityRemove=function(index){if(!canEdit())return;currentPage().activities.splice(index,1);schedule();renderEditor()};
window.stAddPage=function(){if(!canEdit())return;const closingIndex=Math.max(2,active.pages.findIndex(page=>page.kind==='new-hires')),p=newPage(closingIndex+1,'editorial');active.pages.splice(closingIndex,0,p);pageId=p.id;blockId=null;schedule();renderEditor()};window.stCompleteBooklet=function(){if(!canEdit())return;while(active.pages.length%4){const closingIndex=active.pages.findIndex(page=>page.kind==='new-hires');active.pages.splice(closingIndex,0,newPage(closingIndex+1,'editorial'))}schedule();renderEditor()};
window.stDeletePage=function(){const page=currentPage();if(!canEdit()||active.pages.length<=1)return;if(page.mandatory){notify('Esta sección es obligatoria y no puede eliminarse.');return}if(!confirm('¿Eliminar esta página y sus notas?'))return;const i=active.pages.findIndex(p=>p.id===pageId);active.pages.splice(i,1);pageId=active.pages[Math.max(0,i-1)].id;blockId=null;schedule();renderEditor()};
window.stAddBlock=function(type){if(!canEdit()||!['cover','editorial'].includes(currentPage()?.kind||'editorial'))return;const cover=currentPage()?.layout==='cover';const base={id:uid(),type,span:cover?4:12,accent:'teal'};const presets={story:{kicker:'Nueva sección',title:'Titular de la nota',deck:'',body:'Comienza a escribir la historia aquí.',author:'',country:'',site:'',pageRef:cover?'PÁGINA 3':'',items:[]}};Object.assign(base,presets[type]||presets.story);currentPage().blocks.push(base);blockId=base.id;schedule();renderEditor()};
window.stStoryAdd=function(type){const story=currentBlock();if(!canEdit()||story?.type!=='story')return;story.items=story.items||[];const presets={photo:{src:'',caption:'',alt:'',x:50,y:50,zoom:100,height:'medium'},link:{label:'Conoce más',url:''},cta:{title:'Continúa la historia',body:'Escanea el código o visita el enlace.',url:''},contact:{photo:'',name:'',role:'',email:'',country:'',department:''},orgchart:{chart:null}};story.items.push({id:uid(),type,...presets[type]});schedule();renderEditor()};
window.stStoryItemSet=function(index,key,value){const item=currentBlock()?.items?.[index];if(!canEdit()||!item)return;if(item.type==='photo'){if(key==='height')value=['short','medium','tall'].includes(value)?value:'medium';if(key==='x'||key==='y')value=Math.max(0,Math.min(100,Number(value)));if(key==='zoom')value=Math.max(100,Math.min(180,Number(value)))}item[key]=value;schedule();refreshStage()};
window.stEditStoryPhoto=function(event){event?.stopPropagation();const itemId=event?.currentTarget?.dataset?.item,story=currentPage()?.blocks?.find(block=>block.type==='story'&&(block.items||[]).some(item=>item.id===itemId));if(!story)return;blockId=story.id;tab='design';renderEditor();queueMicrotask(()=>{const editor=document.querySelector(`[data-story-item="${itemId}"]`);editor?.scrollIntoView({block:'nearest',behavior:'smooth'});editor?.classList.add('is-editing');editor?.querySelector('input[type="range"]')?.focus()})};
window.stStoryPhotoReset=function(index){const item=currentBlock()?.items?.[index];if(!canEdit()||item?.type!=='photo')return;Object.assign(item,{x:50,y:50,zoom:100});schedule();renderEditor()};
window.stStoryOrgSelect=function(index,key){const item=currentBlock()?.items?.[index],option=availableOrgCharts().find(chart=>chart.key===key);if(!item||!option)return;item.chart=structuredClone(option.chart);schedule();renderEditor()};window.stStoryItemDelete=function(index){if(!canEdit()||!currentBlock()?.items)return;currentBlock().items.splice(index,1);schedule();renderEditor()};window.stStoryItemPhoto=async function(index,input){const file=input.files?.[0],item=currentBlock()?.items?.[index];if(!file||!item)return;input.disabled=true;try{const src=await storeAssetFile(file);item[item.type==='contact'?'photo':'src']=src;if(!active.assets.some(asset=>asset.src===src))active.assets.unshift({id:uid(),name:file.name,src});schedule();renderEditor()}catch(error){notify(error.message||'No se pudo guardar la imagen.')}finally{input.value='';input.disabled=false}};
window.stDeleteBlock=function(id){if(!canEdit())return;const page=currentPage(),i=page.blocks.findIndex(b=>b.id===id);if(i>=0)page.blocks.splice(i,1);if(blockId===id)blockId=null;schedule();renderEditor()};window.stDuplicateBlock=function(id){if(!canEdit())return;const page=currentPage(),source=page.blocks.find(b=>b.id===id);if(!source)return;const copy=structuredClone(source);copy.id=uid();page.blocks.splice(page.blocks.indexOf(source)+1,0,copy);blockId=copy.id;schedule();renderEditor()};
window.stPhotoFile=async function(input){const file=input.files?.[0],b=currentBlock();if(!file||!b)return;input.disabled=true;try{const src=await storeAssetFile(file);b.src=src;if(!active.assets.some(a=>a.src===src))active.assets.unshift({id:uid(),name:file.name,src});schedule();renderEditor()}catch(error){notify(error.message||'No se pudo guardar la imagen.')}finally{input.value='';input.disabled=false}};window.stAssetFiles=async function(input){const files=[...(input.files||[])];if(!files.length)return;input.disabled=true;let added=0;try{for(const file of files){try{const src=await storeAssetFile(file);active.assets.unshift({id:uid(),name:file.name,src});added++}catch(error){notify(`${file.name}: ${error.message||'no se pudo guardar'}`)}}if(added){schedule();renderEditor();notify(`${added} ${added===1?'imagen guardada':'imágenes guardadas'} en Recursos.`)}}finally{input.value='';input.disabled=false}};window.stUseAsset=function(id){if(!canEdit())return;const asset=active.assets.find(a=>a.id===id),story=currentBlock(),photo=story?.type==='story'&&story.items?.find(item=>item.type==='photo');if(!asset)return;if(!photo){notify('Selecciona una nota que tenga una fotografía.');return}photo.src=asset.src;schedule();renderEditor()};window.stDeleteAsset=function(id){if(!canEdit())return;active.assets=active.assets.filter(a=>a.id!==id);schedule();renderEditor()};
function loadRosterParser(){if(window.XLSX)return Promise.resolve(window.XLSX);return new Promise((resolve,reject)=>{const existing=document.querySelector('script[data-st-xlsx]');if(existing){existing.addEventListener('load',()=>resolve(window.XLSX),{once:true});existing.addEventListener('error',reject,{once:true});return}const script=document.createElement('script');script.dataset.stXlsx='true';script.src='https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';script.onload=()=>resolve(window.XLSX);script.onerror=()=>reject(new Error('No se pudo cargar el lector de Excel'));document.head.append(script)})}

function cleanHeader(value){return String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'')}

function rosterValue(row,names){const entries=Object.entries(row),keys=names.map(cleanHeader);const found=entries.find(([key])=>keys.includes(cleanHeader(key)));return found?String(found[1]??'').trim():''}

function normalizeRosterRow(row){return{id:uid(),name:rosterValue(row,['nombre','nombre completo','colaborador','name']),date:rosterValue(row,['fecha','cumpleaños','cumpleanos','dia','birthday']),role:rosterValue(row,['puesto','cargo','posición','posicion','role']),department:rosterValue(row,['departamento','area','área','department']),company:rosterValue(row,['empresa','sede','company']),country:rosterValue(row,['pais','país','country']),photo:''}}
window.stRosterImport=async function(input){const file=input.files?.[0],page=currentPage();if(!file||!page)return;try{const XLSX=await loadRosterParser(),data=await file.arrayBuffer(),book=XLSX.read(data,{type:'array',cellDates:true}),sheet=book.Sheets[book.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:false});const people=rows.map(normalizeRosterRow).filter(person=>person.name);if(!people.length){notify('No encontré filas con una columna de nombre. Revisa los encabezados.');return}page.people=people;schedule();renderEditor();notify(`${people.length} personas importadas.`)}catch(error){notify(error?.message||'No se pudo leer el archivo.')}finally{input.value=''}};
window.stRosterSet=function(index,key,value){const person=currentPage()?.people?.[index];if(!canEdit()||!person)return;person[key]=value;schedule();refreshStage()};window.stRosterRemove=function(index){if(!canEdit())return;currentPage().people.splice(index,1);schedule();renderEditor()};window.stRosterPhoto=async function(index,input){const file=input.files?.[0],person=currentPage()?.people?.[index];if(!file||!person)return;input.disabled=true;try{const src=await storeAssetFile(file);person.photo=src;if(!active.assets.some(asset=>asset.src===src))active.assets.unshift({id:uid(),name:file.name,src});schedule();renderEditor()}catch(error){notify(error.message||'No se pudo guardar la foto.')}finally{input.value='';input.disabled=false}};window.stRosterAsset=function(index,id){const person=currentPage()?.people?.[index],asset=active.assets.find(item=>item.id===id);if(!person||!asset)return;person.photo=asset.src;schedule();renderEditor()};window.stRosterTemplate=function(){const csv='Nombre,Fecha,Puesto,Departamento,Empresa,Pais\n';const blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='plantilla-sierra-times.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
window.stAddComment=function(){const input=document.getElementById('st-comment-input'),text=input?.value.trim();if(!text)return;active.comments.unshift({id:uid(),pageId,blockId,text,author:userName(),createdAt:new Date().toISOString(),resolved:false});schedule();renderEditor()};window.stResolveComment=function(id){const c=active.comments.find(x=>x.id===id);if(!c)return;c.resolved=!c.resolved;schedule();renderEditor()};
window.stGenerateQr=function(){renderQrs();notify('Código QR actualizado. La dirección original permanece visible.')};function renderQrs(){document.querySelectorAll('[data-st-qr]').forEach(canvas=>{const value=canvas.dataset.stQr;if(!value||typeof QRCode==='undefined'){canvas.style.display='none';return}canvas.style.display='block';QRCode.toCanvas(canvas,value,{width:152,margin:1,color:{dark:'#171719',light:'#ffffff'}}).catch?.(()=>{})})}
window.stFinalize=function(){if(!canEdit())return;if(active.pages.length%4){notify('Completa el cuadernillo a un múltiplo de cuatro antes de terminarlo.');return}if(active.comments.some(c=>!c.resolved)&&!confirm('Hay comentarios abiertos. ¿Terminar el boletín de todos modos?'))return;if(!confirm('Al terminarlo ya no se podrá editar. Podrás exportarlo o crear una copia de corrección.'))return;active.state='final';active.finalizedAt=new Date().toISOString();persist();renderEditor()}
const finalizeIssue=window.stFinalize;
window.stFinalize=function(){if(!featuredStories().length){notify('Elige al menos una nota interior para la portada antes de terminar el boletín.');return}finalizeIssue()};
window.stExportDialog=function(){const invalid=active.pages.length%4!==0;document.body.insertAdjacentHTML('beforeend',`<div class="st-modal" id="st-export-modal" onclick="if(event.target===this)this.remove()"><div class="st-modal-card"><div class="st-modal-head"><div><h2>Exportar SIERRA Times</h2><small>Previsualiza cada adaptación o descarga el archivo correspondiente.</small></div><button class="icon-btn" onclick="document.getElementById('st-export-modal').remove()">${icon('x',17)}</button></div><div class="st-modal-body"><div class="st-export-grid"><button class="st-export-option" onclick="stOpenPreview('email')">${icon('mail',22)}<b>Correo continuo</b><small>Vista corrida sin folios, pies de página ni marcas de impresión. Incluye descarga HTML.</small></button><button class="st-export-option" onclick="stExportPdf()">${icon('file-text',22)}<b>PDF editorial</b><small>Páginas carta, folios y enlaces; descarga inmediata.</small></button><button class="st-export-option" ${invalid?'disabled title="Completa el múltiplo de cuatro"':''} onclick="stExportPrint()">${icon('printer',22)}<b>Pliego de imprenta</b><small>Doble carta, imposición de cuadernillo y alta resolución.</small></button><button class="st-export-option" onclick="stOpenPreview('screen')">${icon('monitor',22)}<b>Pantallas 16:9</b><small>Escenas independientes, sin pliegos. Incluye descarga HTML.</small></button></div>${invalid?`<p class="st-page-count is-warning">La salida de imprenta estará disponible cuando la edición tenga páginas completas para cuadernillo.</p>`:''}</div></div></div>`)}

function exportStyle(){return`<style>@font-face{font-family:"Manuskript Gothisch";src:url("assets/fonts/Manuskript-Gothisch-UNZ1A.ttf") format("truetype");font-weight:400;font-style:normal}body{margin:0;background:#e9eae7;font-family:Aeonik,Arial,sans-serif}.export-wrap{display:grid;gap:32px;justify-items:center;padding:32px}.st-sheet{width:816px;min-height:1056px;box-sizing:border-box;background:#fff;padding:30px;position:relative;overflow:hidden;color:#171719}.st-sheet-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px;align-items:start}.st-block{grid-column:span 12;align-self:start}.st-span-6{grid-column:span 6}.st-span-4{grid-column:span 4}.st-span-8{grid-column:span 8}.st-masthead{display:flex;align-items:end;justify-content:space-between;border-bottom:1px solid;padding-bottom:4px}.st-masthead-logo{font:400 21px/.85 "Manuskript Gothisch","Times New Roman",serif}.st-cover-masthead{display:grid;color:#111}.st-cover-double-rule{height:7px;border-top:2px solid #111;border-bottom:1px solid #111}.st-cover-name{padding:15px 0 10px;text-align:center;white-space:nowrap;font:400 88px/.8 "Manuskript Gothisch","Times New Roman",serif;letter-spacing:-.025em}.st-cover-rule{height:1px;background:#111}.st-cover-date{padding:7px 0 6px;text-align:center;font:600 16px/1 Aeonik,Arial,sans-serif;text-transform:uppercase}.st-section-kicker{margin:0 0 7px;text-transform:uppercase;color:#171719;font:bold 10px Arial;letter-spacing:.12em}.st-title{margin:0;font:600 34px/1 "Source Serif 4",Georgia,serif}.st-title.is-hero{font-size:54px}.st-deck{margin:10px 0 0;font:16px/1.35 "Source Serif 4",Georgia,serif}.st-story p{font:13px/1.47 Arial}.st-cover-story{padding:4px 0 10px;border-bottom:1px solid #171719}.st-cover-story.st-span-4{padding-left:14px;border-left:1px solid #171719}.st-cover-columns{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:14px;align-items:start}.st-cover-columns.is-single{grid-template-columns:1fr}.st-cover-column{display:grid;align-content:start;gap:14px;min-width:0}.st-cover-side{padding-left:14px;border-left:1px solid #171719}.st-cover-columns .st-cover-story{grid-column:auto}.st-cover-columns .st-cover-side .st-cover-story{padding-left:0;border-left:0}.st-cover-page-ref{margin-top:11px;font:bold 9px/1 monospace;letter-spacing:.08em}.st-cover-page-ref:after{content:" →"}.st-photo{min-height:250px;position:relative;overflow:hidden}.st-sheet[data-layout="cover"] .st-photo{min-height:300px}.st-photo img{width:100%;height:100%;object-fit:cover}.st-photo-placeholder{display:none}.st-caption{position:absolute;bottom:0;color:#fff;background:#0009;padding:8px}.st-quote,.st-insert,.st-cta,.st-contact,.st-note{padding:16px;border-top:4px solid #9e00cb}.st-cta{display:grid;grid-template-columns:1fr auto}.st-qr{width:76px}.st-folio{position:absolute;left:30px;right:30px;bottom:15px;display:flex;justify-content:space-between;border-top:1px solid;padding-top:6px;font-size:8px}.st-sheet[data-layout="cover"] .st-folio{display:none}.st-block-tools{display:none}.email .export-wrap{gap:0;padding:32px}.email .st-sheet{min-height:auto;aspect-ratio:auto;box-shadow:none;border:0}.email .st-folio,.email .st-page-meta{display:none}.email .st-sheet-grid,.email .st-cover-columns{display:block}.email .st-cover-side{padding-left:0;border-left:0}.email .st-block{margin-bottom:22px}.screen .st-sheet{width:1280px;min-height:720px;aspect-ratio:16/9}.screen .st-folio{display:none}@media print{body{background:white}.export-wrap{display:block;padding:0}.st-sheet{break-after:page;margin:0}}</style>`}
async function exportDoc(kind,body){const w=open('','_blank');if(!w){notify('Permite ventanas emergentes para abrir la exportación.');return null}let html=`<!doctype html><html><head><meta charset="utf-8"><base href="${attr(document.baseURI)}"><title>${safe(active.title)} · ${kind}</title><link rel="stylesheet" href="css/sierra-times.css"><script src="https://cdn.jsdelivr.net/npm/qrcode@1/build/qrcode.min.js"><\/script>${exportStyle()}</head><body class="${kind}">${body}</body></html>`;if(typeof indexAssets!=='undefined')html=await indexAssets.html(html);w.document.write(html);w.document.close();setTimeout(()=>{w.document.querySelectorAll('[data-st-qr]').forEach(c=>{const v=c.dataset.stQr;if(v&&w.QRCode)w.QRCode.toCanvas(c,v,{width:152})})},500);return w}

function channelMarkup(kind){if(kind==='screen'){const scenes=active.pages.flatMap((p,pi)=>p.kind&&!['cover','editorial'].includes(p.kind)?[pageHtml(p,pi,'screen',true)]:p.blocks.filter(b=>!b.internal).map(b=>{const scene={...p,id:`${p.id}-${b.id}`,blocks:[b]};return pageHtml(scene,pi,'screen',true)})).join('');return`<main class="export-wrap">${scenes}</main>`}const channelName=kind==='email'?'email':'print';return`<main class="export-wrap">${active.pages.map((p,i)=>pageHtml(p,i,channelName)).join('')}</main>`}
async function downloadableDocument(kind){let html=`<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="${attr(document.baseURI)}"><title>${safe(active.title)} · ${kind}</title><link rel="stylesheet" href="css/sierra-times.css"><script src="https://cdn.jsdelivr.net/npm/qrcode@1/build/qrcode.min.js"><\/script>${exportStyle()}</head><body class="${kind}">${channelMarkup(kind)}<script>addEventListener('load',()=>document.querySelectorAll('[data-st-qr]').forEach(c=>{const v=c.dataset.stQr;if(v&&window.QRCode)QRCode.toCanvas(c,v,{width:152})}));<\/script></body></html>`;if(typeof indexAssets!=='undefined')html=await indexAssets.html(html);return html}
window.stDownloadChannel=async function(kind){if(!['email','screen'].includes(kind))return;const blob=new Blob([await downloadableDocument(kind)],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`sierra-times-${active.month.slice(0,7)}-${kind==='email'?'correo':'pantallas'}.html`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(kind==='email'?'Correo continuo descargado.':'Presentación para pantallas descargada.')}
window.stClosePreview=function(){const dialog=document.getElementById('st-preview-dialog');if(!dialog)return;typeof dialog.close==='function'&&dialog.open?dialog.close():dialog.remove()}
window.stOpenPreview=function(kind='full'){document.getElementById('st-export-modal')?.remove();document.getElementById('st-preview-dialog')?.remove();const labels={full:['Vista completa','Todas las páginas en orden editorial.'],email:['Correo continuo','Lectura corrida sin folios ni marcas de impresión.'],screen:['Pantallas 16:9','Escenas adaptadas para presentación, no pliegos.']},[title,description]=labels[kind]||labels.full,download=kind==='full'?`<button class="btn btn-secondary btn-sm" onclick="stExportPdf()">${icon('download',15)} Descargar PDF</button>`:`<button class="btn btn-primary btn-sm" onclick="stDownloadChannel('${kind}')">${icon('download',15)} Descargar ${kind==='email'?'correo':'pantallas'}</button>`,dialog=document.createElement('dialog');dialog.id='st-preview-dialog';dialog.className='st-preview-dialog';dialog.innerHTML=`<div class="st-preview-shell"><header class="st-preview-head"><div><p>${safe(title)}</p><small>${safe(description)}</small></div><div>${download}<button class="icon-btn" aria-label="Cerrar vista previa" onclick="stClosePreview()">${icon('x',18)}</button></div></header><div class="st-preview-content ${kind}">${channelMarkup(kind)}</div></div>`;dialog.addEventListener('close',()=>dialog.remove(),{once:true});document.body.append(dialog);typeof dialog.showModal==='function'?dialog.showModal():dialog.setAttribute('open','');queueMicrotask(()=>{renderQrs();hydrateAssets(dialog)})}
window.stExportEmail=function(){stDownloadChannel('email')};window.stPreviewChannel=function(kind){stOpenPreview(kind)};
window.stExportScreen=function(){stDownloadChannel('screen')};
async function capturePages(){if(exporting)return[];exporting=true;const host=document.createElement('div');host.className='st-print-host';host.style.cssText='position:fixed;left:-10000px;top:0;width:816px;background:white;z-index:-1';host.innerHTML=active.pages.map((p,i)=>pageHtml(p,i,'print')).join('');document.body.append(host);host.querySelectorAll('[data-st-qr]').forEach(canvas=>{const value=canvas.dataset.stQr;if(value&&typeof QRCode!=='undefined')QRCode.toCanvas(canvas,value,{width:152,margin:1})});await hydrateAssets(host);await Promise.all([...host.querySelectorAll('img')].map(image=>image.decode?.().catch(()=>{})||Promise.resolve()));await new Promise(r=>setTimeout(r,120));const canvases=[];try{for(const page of host.querySelectorAll('.st-sheet'))canvases.push(await html2canvas(page,{scale:2,useCORS:true,backgroundColor:'#ffffff',logging:false,width:816,height:1056,windowWidth:816,windowHeight:1056}))}finally{host.remove();exporting=false}return canvases}
window.stExportPdf=async function(){if(!window.jspdf?.jsPDF||!window.html2canvas){notify('El generador todavía no está disponible. Recarga Index.');return}document.getElementById('st-export-modal')?.remove();notify('Preparando PDF editorial…');const canvases=await capturePages();const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'letter',compress:true});canvases.forEach((canvas,i)=>{if(i)pdf.addPage('letter','portrait');pdf.addImage(canvas.toDataURL('image/jpeg',.94),'JPEG',0,0,215.9,279.4)});pdf.setProperties({title:active.title,creator:'SIERRA Index'});pdf.save(`sierra-times-${active.month.slice(0,7)}.pdf`)};
function bookletOrder(n){const out=[];let low=1,high=n;while(low<high){out.push([high,low],[low+1,high-1]);low+=2;high-=2}return out}
window.stExportPrint=async function(){if(active.pages.length%4){notify('El cuadernillo necesita un múltiplo de cuatro páginas.');return}const order=bookletOrder(active.pages.length),spreads=order.map((pair,i)=>`<section style="width:17in;height:11in;display:grid;grid-template-columns:1fr 1fr;break-after:page;overflow:hidden">${pair.map(n=>`<div style="transform:scale(.999);transform-origin:top left">${pageHtml(active.pages[n-1],n-1,'print')}</div>`).join('')}</section>`).join('');const w=await exportDoc('print',spreads);if(w)setTimeout(()=>w.print(),700)};
window.stExportScreen=window.stExportScreen;
window.stDuplicateCorrection=function(){if(!active)return;let copy=structuredClone(active);copy.id=uid();copy.title=`${active.title} · Corrección`;copy.state='working';copy.version=(active.version||1)+1;copy.finalizedAt=null;copy.createdAt=new Date().toISOString();copy.updatedAt=copy.createdAt;copy=normalizeIssue(copy);issues.unshift(copy);active=copy;pageId=copy.pages[0].id;blockId=null;persist();renderEditor()};
window.addEventListener('beforeunload',()=>{channel?.close();remoteChannel?.unsubscribe?.()});
})();
